<style>
.client-create-page{max-width:980px;margin:0 auto;padding:0 0 28px}.client-create-intro{padding:20px 24px;margin:0 0 24px;border:1px solid var(--border-strong);border-radius:18px;background:var(--bg-card)}.client-create-intro strong{font-size:20px;letter-spacing:-.025em}.client-create-intro p,.client-create-hint{color:var(--text-secondary);font-size:14px;line-height:1.6;margin:8px 0}.client-create-intro a{display:inline-block;color:var(--accent,#3155ef);font-size:14px;margin-top:8px}.client-create-page form{padding:28px;border:1px solid var(--border-strong);border-radius:22px;background:var(--bg-card)}.client-create-page .vault-security-panel{border:0;padding:0}.client-create-page input:not([type=checkbox]),.client-create-page select,.client-create-page textarea{width:100%;min-height:46px;border-radius:12px!important;border-color:var(--border-strong)!important;background:var(--bg-input,var(--bg-card))!important;color:var(--text-primary)}.client-create-page label{display:block}.client-create-page button[type=submit],.client-create-page form>div:last-child button,.client-create-page .vault-fields>div:last-child button{background:#3155ef!important;color:white;border-radius:12px;padding:12px 20px}.client-create-page .vault-fields>div{margin-bottom:20px}.client-create-page .vault-fields h3{color:var(--text-primary)}@media(max-width:640px){.client-create-page form,.client-create-intro{padding:18px}.client-create-page .vault-fields .grid-cols-12{display:flex;flex-wrap:wrap}.client-create-page .vault-fields .grid-cols-12 input,.client-create-page .vault-fields .grid-cols-12 select{flex:1 1 160px;min-width:0}.client-create-page .vault-fields .grid-cols-12 button{padding:10px}.client-create-page .vault-fields .col-span-12{width:100%}}
